#' Weak-Instrument-Robust Inference
#'
#' 
#' @param data .
#' @param outcome .
#' @param endog .
#' @param instruments .
#' @param controls .
#' @param absorb .
#' @param cluster .
#' @param weights .
#' @param vce .
#' @param small .
#' @param nullValue .
#' @param level .
#' @param gridWidth .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$tests} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$csets} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$tests$asDF}
#'
#' \code{as.data.frame(results$tests)}
#'
#' @export
ivweak <- function(
    data,
    outcome,
    endog,
    instruments,
    controls,
    absorb,
    cluster,
    weights,
    vce = "classical",
    small = TRUE,
    nullValue = 0,
    level = 95,
    gridWidth = 30,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("ivweak requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(endog)) endog <- jmvcore::resolveQuo(jmvcore::enquo(endog))
    if ( ! missing(instruments)) instruments <- jmvcore::resolveQuo(jmvcore::enquo(instruments))
    if ( ! missing(controls)) controls <- jmvcore::resolveQuo(jmvcore::enquo(controls))
    if ( ! missing(absorb)) absorb <- jmvcore::resolveQuo(jmvcore::enquo(absorb))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if ( ! missing(weights)) weights <- jmvcore::resolveQuo(jmvcore::enquo(weights))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(endog), endog, NULL),
            `if`( ! missing(instruments), instruments, NULL),
            `if`( ! missing(controls), controls, NULL),
            `if`( ! missing(absorb), absorb, NULL),
            `if`( ! missing(cluster), cluster, NULL),
            `if`( ! missing(weights), weights, NULL))


    options <- ivweakOptions$new(
        outcome = outcome,
        endog = endog,
        instruments = instruments,
        controls = controls,
        absorb = absorb,
        cluster = cluster,
        weights = weights,
        vce = vce,
        small = small,
        nullValue = nullValue,
        level = level,
        gridWidth = gridWidth,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- ivweakClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

